<div class="page-header d-print-none"><div class="container-xl"><h2 class="page-title">Tabulation Run #{{ $run->id }}</h2></div></div>
<div class="page-body"><div class="container-xl"><div id="tab-progress" class="card" data-url="{{ route('tabulation.run.status',$run) }}"><div class="card-body"><div class="d-flex justify-content-between mb-2"><strong id="status">{{ strtoupper($run->status) }}</strong><span id="numbers">{{ number_format($run->processed_rows) }} / {{ number_format($run->total_rows) }}</span></div><div class="progress"><div id="bar" class="progress-bar" style="width:{{ $run->progress_percent }}%"></div></div><div id="step" class="text-secondary mt-2">{{ $run->failure_message ?: $run->current_step }}</div><div id="counts" class="mt-3"></div><div id="failure" class="alert alert-danger mt-3 d-none" role="alert"></div></div></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const c=document.getElementById('tab-progress');const poll=()=>fetch(c.dataset.url,{headers:{'Accept':'application/json'}}).then(r=>r.json()).then(d=>{document.getElementById('status').textContent=d.status.toUpperCase();document.getElementById('numbers').textContent=`${d.processed_rows.toLocaleString()} / ${d.total_rows.toLocaleString()}`;document.getElementById('bar').style.width=d.progress_percent+'%';document.getElementById('step').textContent=d.current_step||'';document.getElementById('counts').textContent=`Valid ${d.valid_rows.toLocaleString()} · Warnings ${d.warning_rows.toLocaleString()} · Errors ${d.error_rows.toLocaleString()}`;const failure=document.getElementById('failure');if(d.status==='failed'){failure.textContent=d.failure_message||'Tabulation generation failed. Review the failure and queue a new run.';failure.classList.remove('d-none');return;}if(!d.finished){setTimeout(poll,1500);return;}setTimeout(()=>location.href='{{ route('tabulation.results',['run'=>$run->id]) }}',600);}).catch(()=>setTimeout(poll,2500));poll();});</script>
